        public List<object> ReporteBodegas(FiltrosReportesDTO filtros)
        {
            var query = (from a in _dbContext.Bodegas
                         join b in _dbContext.Catalogos on a.IdDepartamento equals b.IdCatalogo
                         join c in _dbContext.Catalogos on a.IdMunicipio equals c.IdCatalogo
                         join d in _dbContext.TipoBodegas on (int)a.IdTipoBodega equals d.IdTipoBodega into ds
                         from d in ds.DefaultIfEmpty()
                         where a.Estado == 0
                                && b.Tipo == "DEPARTAMENTO"
                                && c.Tipo == "MUNICIPIO"
                         orderby a.NombreBodega
                         select new
                         {
                             a.NombreBodega,
                             a.DireccionBodega,
                             a.IdDepartamento,
                             a.IdMunicipio,
                             a.IdTipoBodega,
                             Departamento = b.Descripcion,
                             Municipio = c.Descripcion,
                             TipoBodega = d.NombreTipoBodega
                         }).ToList<object>();

            return query;
        }

        public List<object> ReporteMovimientoProductos(FiltrosReportesDTO filtros)
        {
            var query = (from a in _dbContext.MovimientosProductos
                         join b in _dbContext.Bodegas on a.IdBodega equals (int)b.IdBodega
                         join c in _dbContext.ProductoAlimenticio on a.IdProductoAlimenticio equals (int)c.IdProductoAlimenticio
                         join d in _dbContext.PresentacionPA on a.IdPresentacion equals (int)d.IdPresentacionPA
                         join e in _dbContext.UnidadMedida on a.IdUnidadMedida equals (int)e.IdUnidadMedida
                         where a.Estado == 0
                         orderby a.IdProductoAlimenticio
                         select new
                         {
                             b.NombreBodega,
                             c.NombrePA,
                             d.NombrePresentacionPA,
                             a.CantidadUnidad,
                             e.NombreUnidadMedida,
                             a.Existencias,
                             a.FechaVencimiento,

                             b.IdBodega,
                             c.IdProductoAlimenticio,
                             d.IdPresentacionPA,
                             e.IdUnidadMedida
                         });

            query = (from a in query
                     where (filtros.IdBodega == decimal.Zero || filtros.IdBodega == a.IdBodega) &&
                           (filtros.IdProductoAlimenticio == decimal.Zero || filtros.IdProductoAlimenticio == a.IdProductoAlimenticio) &&
                           (filtros.IdPresentacion == decimal.Zero || filtros.IdPresentacion == a.IdPresentacionPA) &&
                           (filtros.IdUnidadMedida == decimal.Zero || filtros.IdUnidadMedida == a.IdUnidadMedida)
                     select a
                     );

            var listado = query.ToList<object>();

            return listado;
        }

        public List<object> ReportePersonalBodegas(FiltrosReportesDTO filtros)
        {
            var query = (from a in _dbContext.PersonalBodegas
                         join b in _dbContext.Bodegas on (int)a.IdBodega equals b.IdBodega
                         join c in _dbContext.RenglonesPresupuestarios on (int)a.IdRenglonPresupuestario equals c.IdRenglonPresupuestario
                         join d in _dbContext.Puestos on (int)a.IdPuesto equals d.IdPuesto
                         where a.Estado == 0
                         orderby b.NombreBodega
                         select new
                         {
                             b.NombreBodega,
                             b.DireccionBodega,
                             a.Dpi,
                             a.Nit,
                             a.Nombres,
                             a.Apellidos,
                             a.IdPuesto,
                             a.IdBodega,
                             a.IdRenglonPresupuestario,
                             a.Email,
                             a.Telefono,
                             c.Renglon,
                             d.NombrePuesto
                         }).ToList<object>();

            return query;
        }


        public List<dynamic> ReporteExistenciasProducto(FiltrosReportesDTO filtros)
        {

            var query = (from a in _dbContext.Kardex
                         join b in _dbContext.Bodegas on a.IdBodega equals (int)b.IdBodega
                         join c in _dbContext.PresentacionPA on a.IdPresentacion equals (int)c.IdPresentacionPA into cs
                         from c in cs.DefaultIfEmpty()
                         join d in _dbContext.Convenio on a.IdConvenio equals (int)d.IdConvenio
                         join e in _dbContext.ProductoAlimenticio on a.IdProductoAlimenticio equals (int)e.IdProductoAlimenticio
                         join f in _dbContext.UnidadMedida on a.IdUnidadMedida equals (int)f.IdUnidadMedida
                         // LEFT JOIN entre Kardex e IngresoAlimentos
                         join ga in _dbContext.ProductosIngreso on a.IdRegistro equals (int)ga.IdProductosIngreso into gas
                         from ga in gas.DefaultIfEmpty()
                         join g in _dbContext.IngresoAlimentos on ga.IdIngresoAlimentos equals (int?)g.IdIngresoAlimentos into ingresoJoin
                         from g in ingresoJoin.DefaultIfEmpty()
                         join h in _dbContext.Programa on g.IdPrograma equals (int?)h.IdPrograma into programaJoin
                         from h in programaJoin.DefaultIfEmpty()
                         join bd in _dbContext.Bodegas on g.IdBodegaRecibe equals (int?)bd.IdBodega into bds
                         from bd in bds.DefaultIfEmpty()
                             // LEFT JOIN entre Kardex y EgresoAlimentos
                         join ia in _dbContext.DetalleEgresoAlimentos on a.IdRegistro equals (int)ia.IdDetalleEgresoAlimentos into ias
                         from ia in ias.DefaultIfEmpty()
                         join i in _dbContext.EgresoAlimentos on ia.IdEgresoAlimentos equals (int?)i.IdEgresoAlimentos into egresoJoin
                         from i in egresoJoin.DefaultIfEmpty()
                         join j in _dbContext.Programa on i.IdPrograma equals (int?)j.IdPrograma into js
                         from j in js.DefaultIfEmpty()
                         join jd in _dbContext.Bodegas on i.IdBodegaDestino equals (int?)jd.IdBodega into jds
                         from jd in jds.DefaultIfEmpty()

                         where a.Estado == 0

                         select new
                         {
                             NombreBodega = b.NombreBodega,
                             NombrePresentacionPA = c.NombrePresentacionPA == null ? "" : c.NombrePresentacionPA,
                             NombreConvenio = d.NombreConvenio,
                             FechaMovimiento = a.FechaMovimiento,
                             NombrePA = e.NombrePA,

                             CantidadUnidad = a.CantidadUnidad == null ? (decimal?)null : a.CantidadUnidad,
                             NombreUnidadMedida = f.NombreUnidadMedida,
                             NombrePrograma = h != null ? h.NombrePrograma : null,
                             Tabla = a.Tabla,
                             NoActa = g != null ? g.NoActa : null,
                             Despacho = a.Tabla == "PRODUCTOS_INGRESO" ? g.NoActa : i.NoDespachoAlmacen,
                             Ingreso = a.Ingreso == null ? (decimal?)null : a.Ingreso,
                             Egreso = a.Egreso ?? (decimal?)null,
                             Saldo = a.Saldo ?? (decimal?)null,

                             Programa = a.Tabla == "PRODUCTOS_INGRESO" ? h.NombrePrograma : j.NombrePrograma,

                             BodegaDestino = a.Tabla == "PRODUCTOS_INGRESO" ? bd.NombreBodega ?? "" : jd.NombreBodega ?? i.DireccionFinal,

                             // IDs
                             IdBodega = b.IdBodega,
                             IdProductoAlimenticio = e.IdProductoAlimenticio,
                             IdPresentacionPA = c.IdPresentacionPA == null ? (long?)null : c.IdPresentacionPA,
                             IdUnidadMedida = f.IdUnidadMedida,
                             IdConvenio = a.IdConvenio
                         }
            );

            query = (from a in query
                     where (filtros.IdBodega == decimal.Zero || filtros.IdBodega == a.IdBodega) &&
                           (filtros.IdProductoAlimenticio == decimal.Zero || filtros.IdProductoAlimenticio == a.IdProductoAlimenticio) &&
                           (filtros.IdUnidadMedida == decimal.Zero || filtros.IdUnidadMedida == a.IdUnidadMedida) &&
                           (filtros.IdConvenio == decimal.Zero || filtros.IdConvenio == a.IdConvenio)
                     orderby a.FechaMovimiento descending
                     select a
                     );

            var listado = query.ToList<dynamic>();

            return listado;
        }


        public List<object> ReporteConvenios(FiltrosReportesDTO filtros)
        {
            var query = (from a in _dbContext.Convenio
                         where a.Estado == 0
                         orderby a.NombreConvenio
                         select new
                         {
                             a.NombreConvenio,
                             a.Descripcion,
                             a.VidaUtil,
                             a.TotalRaciones
                         }).ToList<object>();
            return query;
        }


        public List<dynamic> ReporteRaciones(FiltrosReportesDTO filtros)
        {
            var query = (from a in _dbContext.RacionMaestro
                         join b in _dbContext.RacionDetalle on a.IdRacionMaestro equals (int)b.IdRacionMaestro
                         join c in _dbContext.Programa on a.IdPrograma equals (int)c.IdPrograma
                         join d in _dbContext.Convenio on a.IdConvenio equals (int)d.IdConvenio
                         join e in _dbContext.ProductoAlimenticio on b.IdProductoAlimenticio equals (int)e.IdProductoAlimenticio
                         join f in _dbContext.UnidadMedida on b.IdUnidadMedida equals (int)f.IdUnidadMedida
                         where a.Estado == 0 && b.Estado == 0
                         orderby a.IdRacionMaestro
                         select new
                         {
                             a.IdRacionMaestro,
                             a.IdPrograma,
                             a.IdConvenio,
                             a.TotalKilocalorias,
                             a.TotalCarbohidratos,
                             a.TotalProteinas,
                             a.TotalGrasas,
                             a.PorcentajeKilocalorias,
                             a.PorcentajeCarbohidratos,
                             a.PorcentajeProteinas,
                             a.PorcentajeGrasas,

                             b.IdProductoAlimenticio,
                             b.CantidadMedida,
                             b.IdUnidadMedida,
                             b.Kilocalorias,
                             b.Carbohidratos,
                             b.Proteinas,
                             b.Grasas,

                             NombrePrograma = c.NombrePrograma == null ? "" : c.NombrePrograma.ToUpper(),
                             NombreConvenio = d.NombreConvenio == null ? "" : d.NombreConvenio.ToUpper(),
                             e.NombrePA,
                             f.NombreUnidadMedida,

                         });

            query = (from a in query
                     where (filtros.IdConvenio == decimal.Zero || filtros.IdConvenio == a.IdConvenio)
                     select a
                     );

            var listado = query.ToList<dynamic>();

            return listado;
        }

        public List<dynamic> ReporteInventarioAlimentos(FiltrosReportesDTO filtros)
        {
            var query = (from a in _dbContext.MovimientosProductos
                         join b in _dbContext.ProductoAlimenticio on a.IdProductoAlimenticio equals (int)b.IdProductoAlimenticio
                         join c in _dbContext.PresentacionPA on a.IdPresentacion equals (int?)c.IdPresentacionPA into presentacionJoin
                         from c in presentacionJoin.DefaultIfEmpty()
                         join d in _dbContext.UnidadMedida on a.IdUnidadMedida equals (int?)d.IdUnidadMedida into unidadJoin
                         from d in unidadJoin.DefaultIfEmpty()
                         join e in _dbContext.Convenio on a.IdConvenio equals (int?)e.IdConvenio into convenioJoin
                         from e in convenioJoin.DefaultIfEmpty()
                         join f in _dbContext.Bodegas on a.IdBodega equals (int?)f.IdBodega into bodegaJoin
                         from f in bodegaJoin.DefaultIfEmpty()
                         where a.Estado == 0
                         orderby a.IdBodega, a.FechaVencimiento ascending
                         select new
                         {
                             NombreBodega = f != null ? f.NombreBodega : "",
                             Convenio = e != null ? e.NombreConvenio : "",
                             NombreProducto = b.NombrePA,
                             Presentacion = c != null ? c.NombrePresentacionPA : "",
                             UnidadMedida = d != null ? d.NombreUnidadMedida : "",
                             a.CantidadUnidad,
                             FechaVencimiento = a.FechaVencimiento ?? null,

                             IdConvenio = a.IdConvenio ?? null,
                             IdBodega = a.IdBodega ?? null,
                             IdProductoAlimenticio = a.IdProductoAlimenticio ?? null,
                             IdPresentacion = a.IdPresentacion ?? null,
                             IdUnidadMedida = a.IdUnidadMedida ?? null
                         });


            query = (from a in query
                     where (filtros.IdConvenio == decimal.Zero || filtros.IdConvenio == a.IdConvenio) &&
                           (filtros.IdBodega == decimal.Zero || filtros.IdBodega == a.IdBodega)
                     select a
                     );

            var listado = query.ToList<dynamic>();

            return listado;
        }

        public List<dynamic> ReporteConstanciaSalidaAlimentos(FiltrosReportesDTO filtros)
        {
            var query = (from a in _dbContext.SolicitudSalidaAlimentos
                         join b in _dbContext.DetalleSalidaAlimentos on a.IdSolicitudSalidaAlimentos equals (int)b.IdSolicitudSalidaAlimentos
                         join c in _dbContext.Programa on a.IdPrograma equals (int?)c.IdPrograma into programaJoin
                         from c in programaJoin.DefaultIfEmpty()
                         join d in _dbContext.ProductoAlimenticio on b.IdProductoAlimenticio equals (int?)d.IdProductoAlimenticio into productoJoin
                         from d in productoJoin.DefaultIfEmpty()
                         join de in _dbContext.PresentacionPA on b.IdPresentacion equals (int?)de.IdPresentacionPA into presentacionJoin
                         from de in presentacionJoin.DefaultIfEmpty()
                         join e in _dbContext.Transportistas on a.IdTransportista equals (int?)e.IdTransportista into transportistaJoin
                         from e in transportistaJoin.DefaultIfEmpty()
                         join f in _dbContext.Vehiculos on a.IdVehiculo equals (int?)f.IdVehiculo into vehiculoJoin
                         from f in vehiculoJoin.DefaultIfEmpty()
                         join g in _dbContext.Pilotos on a.IdPiloto equals (int?)g.IdPiloto into pilotoJoin
                         from g in pilotoJoin.DefaultIfEmpty()
                         join h in _dbContext.EgresoAlimentos on a.IdEgresoAlimentos equals (int?)h.IdEgresoAlimentos into egresoJoin
                         from h in egresoJoin.DefaultIfEmpty()
                         join i in _dbContext.Convenio on h.IdConvenio equals (int?)i.IdConvenio into convenioJoin
                         from i in convenioJoin.DefaultIfEmpty()
                         join j in _dbContext.Bodegas on h.IdBodegaDestino equals (int?)j.IdBodega into bodegaJoin
                         from j in bodegaJoin.DefaultIfEmpty()
                         join k in _dbContext.Catalogos on j.IdDepartamento equals (int?)k.IdCatalogo into departamentoJoin
                         from k in departamentoJoin.DefaultIfEmpty()
                         join l in _dbContext.Catalogos on j.IdMunicipio equals (int?)l.IdCatalogo into municipioJoin
                         from l in municipioJoin.DefaultIfEmpty()

                         where a.Estado == 0 && b.Estado == 0

                         select new
                         {
                             NombrePrograma = c != null ? c.NombrePrograma : "",
                             Convenio = i != null ? i.NombreConvenio : "",
                             a.NoConstancia,
                             a.FechaDespacho,
                             BodegaDestino = j != null ? j.NombreBodega : "",
                             DepartamentoDestino = k != null ? k.Descripcion : "",
                             f.PlacaPlataforma,
                             g.NombresPiloto,
                             e.NombreTransportista,
                             g.NoLicencia,
                             f.PlacaCabezal,
                             NombreProducto = d != null ? d.NombrePA : "",
                             b.CantidadSalida,
                             Presentacion = de != null ? de.NombrePresentacionPA : "",
                             b.EstadoProducto,
                             h.NoDespachoAlmacen
                         });



            query = (from a in query
                     where (filtros.NoConstancia == null || filtros.NoConstancia.ToUpper().Trim() == a.NoConstancia.ToUpper().Trim())
                     select a
                     );

            var listado = query.ToList<dynamic>();

            return listado;
        }

        public List<dynamic> ReporteAPA(FiltrosReportesDTO filtros, int id_estado)
        {
            var query = from s in _dbContext.Solicitudes
                        join d in _dbContext.Catalogos on s.Departamento equals (int?)d.IdCatalogo into departamentoJoin
                        from departamento in departamentoJoin.DefaultIfEmpty()
                        join m in _dbContext.Catalogos on s.Municipio equals (int?)m.IdCatalogo into municipioJoin
                        from municipio in municipioJoin.DefaultIfEmpty()
                        join p in _dbContext.Catalogos on s.IdProyecto equals (int?)p.IdCatalogo into proyectoJoin
                        from proyecto in proyectoJoin.DefaultIfEmpty()
                        join e in _dbContext.EstadoSolicitud on s.IdEstadoSolicitud equals e.IdEstadoSolicitud into estadoJoin
                        from estado in estadoJoin.DefaultIfEmpty()
                        where s.Restrictiva == 0 &&
                              s.IdEstadoSolicitud >= id_estado &&
                              s.Depto == "2" &&
                              s.Rechazada == 0
                        select new
                        {
                            // Propiedades de Solicitud
                            s.IdSolicitud,
                            s.Codigo,
                            s.Correlativo,
                            s.Comunidad,
                            s.FechaRegistro,
                            s.Raciones,
                            s.Departamento,
                            s.Municipio,
                            s.Estado,
                            s.TecnicoObservaciones,
                            // Nombres de los catálogos
                            DepartamentoNombre = departamento.Descripcion,
                            MunicipioNombre = municipio.Descripcion,
                            // Nombre del estado
                            EstadoNombre = estado.Nombre,
                            // Propiedades de Proyecto (si las necesitas)
                            ProyectoNombre = proyecto.Descripcion
                        };

            // Aplicar filtros opcionales
            if (filtros.IdDepartamento.HasValue)
            {
                query = query.Where(x => x.Departamento == filtros.IdDepartamento.Value);
            }

            if (filtros.IdMunicipio.HasValue)
            {
                query = query.Where(x => x.Municipio == filtros.IdMunicipio.Value);
            }

            if (filtros.FechaInicio.HasValue)
            {
                query = query.Where(x => x.FechaRegistro >= filtros.FechaInicio.Value);
            }

            if (filtros.FechaFin.HasValue)
            {
                query = query.Where(x => x.FechaRegistro <= filtros.FechaFin.Value);
            }

            var listado = query.ToList<object>();
            return listado;
        }

        public List<dynamic> ReporteEjecucionesAPA(FiltrosReportesDTO filtros)
        {
            var query = from arv in _dbContext.AsignaRacionV2
                        join solicitud in _dbContext.Solicitudes on arv.IdSolicitud equals (int)solicitud.IdSolicitud
                        join municipio in _dbContext.Catalogos on arv.IdMunicipio equals (int)municipio.IdCatalogo
                        join departamento in _dbContext.Catalogos on arv.IdDepartamento equals (int)departamento.IdCatalogo
                        where solicitud.Restrictiva == 0 &&
                              solicitud.IdEstadoSolicitud >= 8 &&
                              solicitud.Depto == "2"
                        select new { arv, solicitud, municipio, departamento };

            // Aplicar filtros opcionales
            if (filtros.IdDepartamento.HasValue)
            {
                query = query.Where(x => x.arv.IdDepartamento == filtros.IdDepartamento.Value);
            }

            if (filtros.IdMunicipio.HasValue)
            {
                query = query.Where(x => x.arv.IdMunicipio == filtros.IdMunicipio.Value);
            }

            if (filtros.FechaInicio.HasValue)
            {
                query = query.Where(x => x.solicitud.FechaRegistro >= filtros.FechaInicio.Value);
            }

            if (filtros.FechaFin.HasValue)
            {
                query = query.Where(x => x.solicitud.FechaRegistro <= filtros.FechaFin.Value);
            }

            var listado = query.ToList<object>();

            return listado;
        }

