        public async Task<string> GenerarReporte(int tipoReporte, FiltrosReportesDTO filtros)
        {
            string tabla = "<table style='border-collapse: collapse;'>{0}</table>";

            if (tipoReporte == (int)TipoReporteEnum.ConstanciaSalidaAlimentos)
                tabla = "<table style=' border-collapse: collapse; border: 1px solid black;'>{0}</table>";

            string header = GenerarEncabezadoReporte(tipoReporte);
            string tbody = GenerarCuerpoReporte(tipoReporte, filtros);

            string body = header + tbody;

            tabla = string.Format(tabla, body);

            if (tipoReporte == (int)TipoReporteEnum.ConstanciaSalidaAlimentos)
            {

            }

            return tabla;
        }

